function TodoItem({ todo, onToggle, onDelete, onEdit }) {
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState(todo.text);
  function save() {
    const t = draft.trim();
    if (t) onEdit(todo.id, t);
    else setDraft(todo.text);
    setEditing(false);
  }
  return (
    <li className="item">
      <input type="checkbox" checked={todo.done} onChange={() => onToggle(todo.id)} aria-label={"Toggle " + todo.text} />
      {editing ? (
        <input autoFocus value={draft} onChange={(e) => setDraft(e.target.value)} onBlur={save}
          onKeyDown={(e) => e.key === "Enter" && save()} />
      ) : (
        <span className={todo.done ? "done" : ""} onDoubleClick={() => setEditing(true)} title="Double-click to edit">
          {todo.text}
        </span>
      )}
      <button onClick={() => onDelete(todo.id)} aria-label={"Delete " + todo.text}>x</button>
    </li>
  );
}

function App() {
  const [todos, setTodos] = useState([
    { id: 1, text: "Learn React", done: true },
    { id: 2, text: "Build a todo app", done: false },
  ]);
  const [nextId, setNextId] = useState(3);
  const [text, setText] = useState("");
  const [filter, setFilter] = useState("all");

  const visible = todos.filter((t) => filter === "all" || (filter === "done" ? t.done : !t.done));
  const remaining = todos.filter((t) => !t.done).length;

  function add(e) {
    e.preventDefault();
    const t = text.trim();
    if (!t) return;
    setTodos([...todos, { id: nextId, text: t, done: false }]);
    setNextId(nextId + 1);
    setText("");
  }
  const toggle = (id) => setTodos(todos.map((t) => (t.id === id ? { ...t, done: !t.done } : t)));
  const del = (id) => setTodos(todos.filter((t) => t.id !== id));
  const edit = (id, text) => setTodos(todos.map((t) => (t.id === id ? { ...t, text } : t)));

  return (
    <div className="todo">
      <h3>Todos</h3>
      <form onSubmit={add}>
        <input value={text} onChange={(e) => setText(e.target.value)} placeholder="What needs doing?" />
        <button>Add</button>
      </form>
      <div className="filters">
        {["all", "active", "done"].map((f) => (
          <button key={f} className={f === filter ? "on" : ""} onClick={() => setFilter(f)}>{f}</button>
        ))}
      </div>
      <ul>
        {visible.map((t) => <TodoItem key={t.id} todo={t} onToggle={toggle} onDelete={del} onEdit={edit} />)}
      </ul>
      {visible.length === 0 && <p className="muted">Nothing to show.</p>}
      <p className="muted">
        {remaining} left{" "}
        <button onClick={() => setTodos(todos.filter((t) => !t.done))}>Clear completed</button>
      </p>
    </div>
  );
}

const initial = { past: [], present: 0, future: [] };

function reducer(state, action) {
  const { past, present, future } = state;
  switch (action.type) {
    case "inc":
    case "dec": {
      const next = present + (action.type === "inc" ? 1 : -1);
      return { past: [...past, present], present: next, future: [] };
    }
    case "undo":
      if (past.length === 0) return state;
      return { past: past.slice(0, -1), present: past[past.length - 1], future: [present, ...future] };
    case "redo":
      if (future.length === 0) return state;
      return { past: [...past, present], present: future[0], future: future.slice(1) };
    case "reset":
      return initial;
    default:
      throw new Error("Unknown action " + action.type);
  }
}

function App() {
  const [state, dispatch] = useReducer(reducer, initial);
  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <h2>{state.present}</h2>
      <button onClick={() => dispatch({ type: "dec" })}>-1</button>{" "}
      <button onClick={() => dispatch({ type: "inc" })}>+1</button>{" "}
      <button onClick={() => dispatch({ type: "undo" })} disabled={state.past.length === 0}>Undo</button>{" "}
      <button onClick={() => dispatch({ type: "redo" })} disabled={state.future.length === 0}>Redo</button>{" "}
      <button onClick={() => dispatch({ type: "reset" })}>Reset</button>
      <p style={{ color: "#666" }}>past: [{state.past.join(", ")}] | future: [{state.future.join(", ")}]</p>
    </div>
  );
}

