const ThemeCtx = createContext(null);

function getSystem() {
  try { return window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light"; }
  catch (e) { return "light"; }
}

function ThemeProvider({ children }) {
  const [mode, setMode] = useState(() => {
    try { return localStorage.getItem("demo-theme-mode") || "system"; } catch (e) { return "system"; }
  });
  const [system, setSystem] = useState(getSystem);

  useEffect(() => {
    let mq;
    try { mq = window.matchMedia("(prefers-color-scheme: dark)"); } catch (e) { return; }
    const onChange = () => setSystem(mq.matches ? "dark" : "light");
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  useEffect(() => {
    try { localStorage.setItem("demo-theme-mode", mode); } catch (e) {}
  }, [mode]);

  const resolved = mode === "system" ? system : mode;
  const value = useMemo(() => ({ mode, setMode, resolved }), [mode, resolved]);

  return (
    <ThemeCtx.Provider value={value}>
      <div className="shell" data-theme={resolved}>{children}</div>
    </ThemeCtx.Provider>
  );
}
function useTheme() {
  const ctx = useContext(ThemeCtx);
  if (!ctx) throw new Error("useTheme must be used within ThemeProvider");
  return ctx;
}

function ThemeSwitcher() {
  const { mode, setMode, resolved } = useTheme();
  return (
    <div role="group" aria-label="Theme">
      {["light", "dark", "system"].map((m) => (
        <button key={m} aria-pressed={mode === m} onClick={() => setMode(m)} className={mode === m ? "on" : ""}>{m}</button>
      ))}
      <p>Mode: <b>{mode}</b> | Applied: <b>{resolved}</b></p>
    </div>
  );
}

function App() {
  return (
    <ThemeProvider>
      <h3>Theme switcher</h3>
      <ThemeSwitcher />
      <div className="card">Everything below the provider follows the theme.</div>
    </ThemeProvider>
  );
}

