];
const money = (paise) => new Intl.NumberFormat("en-IN", { style: "currency", currency: "INR" }).format(paise / 100);

function cartReducer(items, action) {
  switch (action.type) {
    case "add": {
      const found = items.find((i) => i.id === action.product.id);
      if (found) return items.map((i) => (i.id === found.id ? { ...i, qty: i.qty + 1 } : i));
      return [...items, { ...action.product, qty: 1 }];
    }
    case "inc":
      return items.map((i) => (i.id === action.id ? { ...i, qty: i.qty + 1 } : i));
    case "dec":
      return items.map((i) => (i.id === action.id ? { ...i, qty: i.qty - 1 } : i)).filter((i) => i.qty > 0);
    case "remove":
      return items.filter((i) => i.id !== action.id);
    case "clear":
      return [];
    default:
      throw new Error("Unknown action " + action.type);
  }
}

function App() {
  const [items, dispatch] = useReducer(cartReducer, []);
  const count = items.reduce((n, i) => n + i.qty, 0);
  const total = items.reduce((s, i) => s + i.price * i.qty, 0);
  return (
    <div className="shop">
      <h3>Products</h3>
      {PRODUCTS.map((p) => (
        <div key={p.id} className="row">
          <span>{p.name} - {money(p.price)}</span>
          <button onClick={() => dispatch({ type: "add", product: p })}>Add</button>
        </div>
      ))}
      <h3>Cart ({count})</h3>
      {items.length === 0 && <p className="muted">Your cart is empty.</p>}
      {items.map((i) => (
        <div key={i.id} className="row">
          <span>{i.name}</span>
          <span>
            <button onClick={() => dispatch({ type: "dec", id: i.id })} aria-label={"Decrease " + i.name}>-</button>
            {" "}{i.qty}{" "}
            <button onClick={() => dispatch({ type: "inc", id: i.id })} aria-label={"Increase " + i.name}>+</button>
            {" "}{money(i.price * i.qty)}{" "}
            <button onClick={() => dispatch({ type: "remove", id: i.id })}>x</button>
          </span>
        </div>
      ))}
      <p><b>Total: {money(total)}</b> {items.length > 0 && <button onClick={() => dispatch({ type: "clear" })}>Clear</button>}</p>
    </div>
  );
}

function format(ms) {
  const cs = Math.floor((ms % 1000) / 10);
  const s = Math.floor(ms / 1000) % 60;
  const m = Math.floor(ms / 60000);
  return String(m).padStart(2, "0") + ":" + String(s).padStart(2, "0") + "." + String(cs).padStart(2, "0");
}

