const STEPS = ["Account", "Profile", "Review"];

function validate(step, d) {
  const e = {};
  if (step === 0) {
    if (!/^\S+@\S+\.\S+$/.test(d.email)) e.email = "Enter a valid email";
    if (d.password.length < 6) e.password = "Min 6 characters";
  }
  if (step === 1) {
    if (!d.name.trim()) e.name = "Name is required";
    if (!d.city) e.city = "Choose a city";
  }
  return e;
}

function Field({ label, name, type = "text", data, errors, onChange, children }) {
  return (
    <div className="f">
      <label>{label}{" "}
        {children || <input name={name} type={type} value={data[name]} onChange={onChange} />}
      </label>
      {errors[name] && <div role="alert" className="err">{errors[name]}</div>}
    </div>
  );
}

function App() {
  const [step, setStep] = useState(0);
  const [data, setData] = useState({ email: "", password: "", name: "", city: "" });
  const [errors, setErrors] = useState({});
  const [done, setDone] = useState(false);

  const onChange = (e) => setData({ ...data, [e.target.name]: e.target.value });

  function next() {
    const errs = validate(step, data);
    setErrors(errs);
    if (Object.keys(errs).length === 0) setStep(step + 1);
  }
  function back() { setErrors({}); setStep(step - 1); }

  if (done) return <div className="wiz"><h3>Welcome, {data.name}!</h3><p>Account created for {data.email}.</p></div>;

  return (
    <div className="wiz">
      <p className="prog">Step {step + 1} of {STEPS.length}: <b>{STEPS[step]}</b></p>
      <progress value={step + 1} max={STEPS.length} />
      {step === 0 && (
        <>
          <Field label="Email" name="email" data={data} errors={errors} onChange={onChange} />
          <Field label="Password" name="password" type="password" data={data} errors={errors} onChange={onChange} />
        </>
      )}
      {step === 1 && (
        <>
          <Field label="Name" name="name" data={data} errors={errors} onChange={onChange} />
          <Field label="City" name="city" data={data} errors={errors} onChange={onChange}>
            <select name="city" value={data.city} onChange={onChange}>
              <option value="">Choose...</option><option>Pune</option><option>Delhi</option><option>Chennai</option>
            </select>
          </Field>
        </>
      )}
      {step === 2 && (
        <dl>
          <dt>Email</dt><dd>{data.email}</dd>
          <dt>Name</dt><dd>{data.name}</dd>
          <dt>City</dt><dd>{data.city}</dd>
        </dl>
      )}
      <div className="nav">
        {step > 0 && <button onClick={back}>Back</button>}
        {step < STEPS.length - 1 && <button onClick={next}>Next</button>}
        {step === STEPS.length - 1 && <button onClick={() => setDone(true)}>Submit</button>}
      </div>
    </div>
  );
}

const DATA = ["apple", "apricot", "banana", "blueberry", "cherry", "grape", "grapefruit", "mango", "orange", "papaya", "peach", "pear", "pineapple", "plum"];

let requests = 0;
function fakeSearch(q) {
  requests += 1;
  const delay = q.length % 2 === 0 ? 700 : 250; // sometimes slow, sometimes fast
  return new Promise((resolve) =>
    setTimeout(() => resolve(DATA.filter((x) => x.includes(q.toLowerCase()))), delay)
  );
}

function useDebounce(value, delay) {
  const [v, setV] = useState(value);
  useEffect(() => {
    const id = setTimeout(() => setV(value), delay);
    return () => clearTimeout(id);
  }, [value, delay]);
  return v;
}

function App() {
  const [query, setQuery] = useState("");
  const debounced = useDebounce(query.trim(), 400);
  const [state, setState] = useState({ status: "idle", results: [] });

  useEffect(() => {
    if (debounced.length < 2) { setState({ status: "idle", results: [] }); return; }
    let ignore = false;
    setState((s) => ({ ...s, status: "loading" }));
    fakeSearch(debounced).then((results) => {
      if (!ignore) setState({ status: "success", results });
    });
    return () => { ignore = true; };
  }, [debounced]);

  return (
    <div style={{ fontFamily: "sans-serif", padding: 12, maxWidth: 320 }}>
      <input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search fruits (min 2 chars)" style={{ width: "100%" }} />
      <p style={{ color: "#666", fontSize: 13 }}>Requests made: {requests}</p>
      {state.status === "idle" && <p>Type at least 2 characters.</p>}
      {state.status === "loading" && <p>Searching...</p>}
      {state.status === "success" && state.results.length === 0 && <p>No results for "{debounced}".</p>}
      <ul>{state.results.map((r) => <li key={r}>{r}</li>)}</ul>
    </div>
  );
}

const TOTAL = 60, PAGE = 12;
const makePage = (start) =>
  Array.from({ length: Math.min(PAGE, TOTAL - start) }, (_, i) => "Item " + (start + i + 1));

function App() {
  const [items, setItems] = useState(() => makePage(0));
  const [loading, setLoading] = useState(false);
  const rootRef = useRef(null);
  const sentinelRef = useRef(null);
  const hasMore = items.length < TOTAL;

  const loadMore = useCallback(() => {
    setLoading(true);
    setTimeout(() => {
      setItems((prev) => (prev.length >= TOTAL ? prev : [...prev, ...makePage(prev.length)]));
      setLoading(false);
    }, 500);
  }, []);

  useEffect(() => {
    if (!hasMore || loading || !sentinelRef.current) return;
    const io = new IntersectionObserver(
      (entries) => { if (entries[0].isIntersecting) loadMore(); },
      { root: rootRef.current, rootMargin: "60px" }
    );
    io.observe(sentinelRef.current);
    return () => io.disconnect();
  }, [hasMore, loading, loadMore]);

  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <div ref={rootRef} style={{ height: 180, overflow: "auto", border: "1px solid #ccc", borderRadius: 6 }}>
        <ul aria-live="polite" style={{ margin: 0, padding: 0, listStyle: "none" }}>
          {items.map((it) => <li key={it} style={{ padding: "8px 10px", borderBottom: "1px solid #eee" }}>{it}</li>)}
        </ul>
        <div ref={sentinelRef} style={{ padding: 8, textAlign: "center", color: "#666" }}>
          {loading ? "Loading..." : hasMore ? "Scroll for more" : "You reached the end"}
        </div>
      </div>
      {hasMore && !loading && <button onClick={loadMore} style={{ marginTop: 8 }}>Load more</button>}
      <p>{items.length} / {TOTAL} loaded</p>
    </div>
  );
}

